     <title>Image Preview</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f4f7fb;
         --panel: rgba(255, 255, 255, 0.82);
         --panel-border: rgba(15, 23, 42, 0.08);
         --text: #0f172a;
         --muted: #64748b;
         --primary: #2563eb;
         --primary-dark: #1d4ed8;
         --danger: #dc2626;
