           url("https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1200&q=80") center/cover;
         box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.18);
       }

       .hero::after {
         content: "";
         position: absolute;
         inset: 0;
         background: linear-gradient(180deg, rgba(15, 23, 42, 0.08), rgba(15, 23, 42, 0.58));
