         text-transform: uppercase;
         letter-spacing: 0.08em;
       }

       .meta-value {
         font-weight: 600;
       }

       .actions {
         display: flex;
         flex-wrap: wrap;
         gap: 12px;
       }

       .button {
         appearance: none;
         border: 0;
         border-radius: 14px;
         padding: 14px 18px;
         font: inherit;
         font-weight: 600;
         cursor: pointer;
         transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
       }

       .button:hover {
         transform: translateY(-1px);
       }

       .button.primary {
         color: white;
         background: linear-gradient(180deg, var(--primary), var(--primary-dark));
         box-shadow: 0 12px 26px rgba(37, 99, 235, 0.28);
       }

       .button.ghost {
         color: var(--text);
         background: rgba(255, 255, 255, 0.84);
         border: 1px solid rgba(148, 163, 184, 0.22);
       }

       dialog {
         width: min(92vw, 460px);
         border: 0;
         border-radius: 28px;
         padding: 0;
         background: transparent;
         box-shadow: none;
       }

       dialog::backdrop {
         background: rgba(15, 23, 42, 0.5);
         backdrop-filter: blur(6px);
       }

       .dialog-shell {
         overflow: hidden;
         border-radius: 28px;
         background: rgba(255, 255, 255, 0.96);
         border: 1px solid rgba(148, 163, 184, 0.2);
         box-shadow: 0 36px 100px rgba(15, 23, 42, 0.28);
       }

       .dialog-art {
         height: 144px;
         background:
           linear-gradient(160deg, rgba(220, 38, 38, 0.92), rgba(15, 23, 42, 0.96)),
           radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.28), transparent 40%);
       }

       .dialog-content {
         padding: 24px;
       }

       .dialog-title {
         margin: 0 0 10px;
         font-size: 1.5rem;
         letter-spacing: -0.03em;
       }

       .dialog-copy {
         margin: 0;
         color: var(--muted);
         line-height: 1.65;
       }

       .dialog-actions {
         display: flex;
         justify-content: flex-end;
         gap: 12px;
         margin-top: 24px;
       }

       .button.danger {
         color: white;
         background: linear-gradient(180deg, var(--danger), var(--danger-dark));
         box-shadow: 0 12px 26px rgba(220, 38, 38, 0.26);
       }

       .button.tertiary {
         color: var(--text);
         background: #f8fafc;
         border: 1px solid rgba(148, 163, 184, 0.22);
       }

       .visually-hidden {
         position: absolute;
         width: 1px;
         height: 1px;
         padding: 0;
         margin: -1px;
         overflow: hidden;
         clip: rect(0, 0, 0, 0);
         white-space: nowrap;
         border: 0;
       }

       @media (max-width: 860px) {
         .preview-card {
           grid-template-columns: 1fr;
         }

         .hero {
           min-height: 360px;
         }
       }
     </style>
   </head>
   <body>
     <main id="app" class="page"></main>

     <dialog id="deleteDialog" aria-labelledby="deleteDialogTitle" aria-describedby="deleteDialogDesc">
       <div class="dialog-shell">
         <div class="dialog-art" aria-hidden="true"></div>
         <div class="dialog-content">
           <h2 id="deleteDialogTitle" class="dialog-title">Delete this image?</h2>
           <p id="deleteDialogDesc" class="dialog-copy">
             This will remove the image from your library and it can&apos;t be undone.
           </p>
           <div class="dialog-actions">
             <button type="button" class="button tertiary" data-action="cancel">Cancel</button>
             <button type="button" class="button danger" data-action="delete">Delete image</button>
           </div>
         </div>
       </div>
     </dialog>

     <script>
       const createElement = (tag, { className = "", attrs = {}, children = "", text = "" } = {}) => {
         const el = document.createElement(tag);
         if (className) el.className = className;
         Object.entries(attrs).forEach(([key, value]) => el.setAttribute(key, value));
         if (text) el.textContent = text;
         if (children) {
           if (typeof children === "string") {
             el.innerHTML = children;
           } else {
             children.forEach((child) => el.appendChild(child));
           }
         }
         return el;
       };

       function MetaCard(label, value) {
         const card = createElement("div", { className: "meta-card" });
         card.append(
           createElement("span", { className: "meta-label", text: label }),
           createElement("div", { className: "meta-value", text: value })
         );
         return card;
       }

       function App() {
         const root = createElement("div", { className: "preview-card" });

         const hero = createElement("section", { className: "hero", attrs: { "aria-label": "Image preview" } });
         hero.append(
           createElement("div", { className: "hero-badge", text: "Preview • 4.2 MB" }),
           createElement("div", {
             className: "hero-caption",
             children: [
               createElement("h1", { text: "Golden hour cityscape" }),
               createElement("p", {
                 text: "A polished preview page with the image front and center, plus a confirmation dialog for destructive actions.",
               }),
             ],
           })
         );

         const details = createElement("section", { className: "details" });
         const header = createElement("div");
         header.append(
           createElement("h2", { text: "Image details" }),
           createElement("p", {
             text: "Review metadata, keep the asset, or remove it from your library using the delete action below.",
           })
         );

         const meta = createElement("div", { className: "meta" });
         meta.append(
           MetaCard("File name", "city-lights.jpg"),
           MetaCard("Uploaded", "Today, 2:18 PM"),
           MetaCard("Dimensions", "4096 × 2731"),
           MetaCard("Owner", "Creative Library")
         );

         const actions = createElement("div", { className: "actions" });
         actions.append(
           createElement("button", { className: "button ghost", text: "Share" }),
           createElement("button", {
             className: "button primary trigger",
             text: "Delete image",
             attrs: { type: "button", "aria-haspopup": "dialog", "aria-controls": "deleteDialog" },
           })
         );

         details.append(header, meta, actions);
         root.append(hero, details);
         return root;
       }

       const app = document.getElementById("app");
       app.appendChild(App());

       const dialog = document.getElementById("deleteDialog");
       const trigger = document.querySelector(".trigger");
       const cancelButton = dialog.querySelector('[data-action="cancel"]');
       const deleteButton = dialog.querySelector('[data-action="delete"]');

       trigger.addEventListener("click", () => {
         if (!dialog.open) {
           dialog.showModal();
         }
       });

       cancelButton.addEventListener("click", () => dialog.close());
       deleteButton.addEventListener("click", () => dialog.close());

       dialog.addEventListener("click", (event) => {
         const rect = dialog.getBoundingClientRect();
         const isBackdropClick =
           event.clientX < rect.left ||
           event.clientX > rect.right ||
           event.clientY < rect.top ||
           event.clientY > rect.bottom;

         if (isBackdropClick) {
           dialog.close();
         }
       });
     </script>
   </body>
